  function notesHero(rows,eyebrow,title,copy){return `<section class="notes-header"><div><div class="notes-kicker">${escValue(eyebrow)}</div><h1>${escValue(title)}</h1><p>${escValue(copy)}</p></div><div class="notes-header-stat"><b>${rows.length}</b><span>ভুল প্রশ্ন</span></div></section>`;}
